window.OMNI_SIM_CORE = {"generated_from": "omni_sim_core/src", "modules": {"omni_sim_core/__init__.py": "\"\"\"Omni-directional robot simulator core (ROS-independent).\n\nThis package deliberately imports *no* rclpy. It runs standalone under pytest\nand parameter sweeps. See docs/spec for the layered architecture:\n\n    body  <- jacobian <- motor    (true plant, numeric integration)\n    nominal model                 (what the controller believes)\n    disturbance / sensors / env   (measurement + environment)\n\nThe single most important invariant: the *true* plant and the *nominal* model\nare configured from independent files and never share state.\n\"\"\"\n\n__version__ = \"1.0.0\"\n", "omni_sim_core/mechanism/__init__.py": "\"\"\"Mechanism parameter layer.\n\nTurns a human-authored robot description (chassis geometry + actuator\ndatasheets) into the physical plant parameters the simulator consumes. Inputs\nlive in ``config/robot/*.yaml`` and ``config/presets/motors/*.yaml``; the output\nis ``config/generated/plant_*.yaml`` plus a drive jacobian for cross-checking.\n\nThis package is ROS-free and GUI-free. It uses ``ruamel.yaml`` (a runtime\ndependency of omni_sim_core) so authored comments and key order survive a\nload/save round-trip. Importing this subpackage is optional: ``import\nomni_sim_core`` never pulls it in, so the rest of the core still imports with\nneither ruamel nor a GUI toolkit present.\n\"\"\"\n", "omni_sim_core/mechanism/schema.py": "\"\"\"Mechanism schema: dataclasses + validation for the robot description.\n\nInput : parsed YAML mappings (from ``config/robot/*.yaml``).\nOutput: validated dataclasses (``Chassis``, ``ActuatorSet``, ``ModelError``).\n\nEverything here is SI (metres, radians, kg, N, A, V, s); the GUI is responsible\nfor mm/degree <-> SI conversion and must never leak display units into this\nlayer. The wheel count is deliberately *not* fixed -- 3-wheel / other omni\nlayouts are a future addition, so ``drive_wheels`` is just a list.\n\"\"\"\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom typing import Any, Optional\n\nSCHEMA_VERSION = 1\n\n\nclass SchemaError(ValueError):\n    \"\"\"Raised when a robot description is structurally invalid.\"\"\"\n\n\ndef _require(mapping: Any, key: str, ctx: str) -> Any:\n    if mapping is None or key not in mapping:\n        raise SchemaError(f\"{ctx}: required key '{key}' is missing\")\n    return mapping[key]\n\n\ndef _xy(value: Any, ctx: str) -> tuple[float, float]:\n    if value is None or len(value) != 2:\n        raise SchemaError(f\"{ctx}: expected [x, y] in metres, got {value!r}\")\n    return (float(value[0]), float(value[1]))\n\n\n# --------------------------------------------------------------------------- #\n# chassis.yaml\n# --------------------------------------------------------------------------- #\n@dataclass\nclass Footprint:\n    shape: str = \"square\"\n    size_m: float = 0.5\n\n    def validate(self) -> None:\n        if self.shape != \"square\":\n            raise SchemaError(f\"footprint.shape '{self.shape}' unsupported \"\n                              \"(only 'square' for now)\")\n        if self.size_m <= 0:\n            raise SchemaError(\"footprint.size_m must be > 0\")\n\n\n@dataclass\nclass CenterOfMass:\n    position_m: tuple[float, float] = (0.0, 0.0)\n    mass_kg: float = 0.0\n    inertia_zz_kgm2: float = 0.0\n\n    def validate(self) -> None:\n        if self.mass_kg <= 0:\n            raise SchemaError(\"center_of_mass.mass_kg must be > 0\")\n        if self.inertia_zz_kgm2 <= 0:\n            raise SchemaError(\"center_of_mass.inertia_zz_kgm2 must be > 0\")\n\n\n@dataclass\nclass DriveWheel:\n    id: str\n    position_m: tuple[float, float]   # ground-contact point, base_link frame\n    drive_axis_rad: float             # direction the wheel produces force\n    radius_m: float\n    gear_ratio: float                 # motor:wheel (REQUIRED -- no default!)\n    actuator_ref: str\n    reverse: bool = False\n\n    def validate(self) -> None:\n        if self.radius_m <= 0:\n            raise SchemaError(f\"wheel '{self.id}': radius_m must be > 0\")\n        if self.gear_ratio <= 0:\n            raise SchemaError(f\"wheel '{self.id}': gear_ratio must be > 0\")\n\n\nODOMETRY_TYPES = (\"dead_wheel\", \"optical\")\n\n\n@dataclass\nclass OdometrySource:\n    \"\"\"A standalone odometry unit, separate from the drive-wheel encoders.\n\n    ``dead_wheel``: a passive (non-driven) measurement wheel rolling along\n    ``measure_axis_rad``; ``optical``: a 2D optical-flow / mouse sensor that\n    reports planar motion directly (no wheel, so radius/axis may be null).\n    \"\"\"\n    id: str\n    type: str                                    # dead_wheel | optical\n    position_m: tuple[float, float]\n    measure_axis_rad: Optional[float] = None     # required for dead_wheel\n    radius_m: Optional[float] = None             # required for dead_wheel\n    encoder_cpr: Optional[int] = None\n\n    def validate(self) -> None:\n        if self.type not in ODOMETRY_TYPES:\n            raise SchemaError(f\"odometry '{self.id}': type '{self.type}' invalid \"\n                              f\"(expected one of {ODOMETRY_TYPES})\")\n        if self.type == \"dead_wheel\":\n            if self.radius_m is None or self.radius_m <= 0:\n                raise SchemaError(f\"odometry '{self.id}': dead_wheel needs radius_m > 0\")\n            if self.measure_axis_rad is None:\n                raise SchemaError(f\"odometry '{self.id}': dead_wheel needs measure_axis_rad\")\n\n\n@dataclass\nclass Chassis:\n    schema_version: int\n    footprint: Footprint\n    center_of_mass: CenterOfMass\n    drive_wheels: list[DriveWheel]\n    odometry: list[OdometrySource] = field(default_factory=list)\n\n    @staticmethod\n    def from_doc(doc: Any) -> \"Chassis\":\n        _check_version(doc, \"chassis.yaml\")\n        fp_raw = _require(doc, \"footprint\", \"chassis.yaml\")\n        footprint = Footprint(shape=str(fp_raw.get(\"shape\", \"square\")),\n                              size_m=float(_require(fp_raw, \"size_m\", \"footprint\")))\n        com_raw = _require(doc, \"center_of_mass\", \"chassis.yaml\")\n        com = CenterOfMass(\n            position_m=_xy(com_raw.get(\"position_m\", [0.0, 0.0]), \"center_of_mass\"),\n            mass_kg=float(_require(com_raw, \"mass_kg\", \"center_of_mass\")),\n            inertia_zz_kgm2=float(_require(com_raw, \"inertia_zz_kgm2\",\n                                           \"center_of_mass\")),\n        )\n        wheels_raw = _require(doc, \"drive_wheels\", \"chassis.yaml\")\n        wheels: list[DriveWheel] = []\n        for w in wheels_raw:\n            wid = str(_require(w, \"id\", \"drive_wheel\"))\n            wheels.append(DriveWheel(\n                id=wid,\n                position_m=_xy(_require(w, \"position_m\", f\"wheel '{wid}'\"),\n                               f\"wheel '{wid}'\"),\n                drive_axis_rad=float(_require(w, \"drive_axis_rad\", f\"wheel '{wid}'\")),\n                radius_m=float(_require(w, \"radius_m\", f\"wheel '{wid}'\")),\n                # gear_ratio is required on purpose: an implicit 1.0 hides a\n                # reflected-inertia error that scales with n^2 (see derive.py).\n                gear_ratio=float(_require(w, \"gear_ratio\", f\"wheel '{wid}'\")),\n                actuator_ref=str(_require(w, \"actuator_ref\", f\"wheel '{wid}'\")),\n                reverse=bool(w.get(\"reverse\", False)),\n            ))\n        # odometry is optional (standalone units, in addition to drive encoders)\n        odo: list[OdometrySource] = []\n        for o in (doc.get(\"odometry\", []) or []):\n            oid = str(_require(o, \"id\", \"odometry\"))\n            odo.append(OdometrySource(\n                id=oid,\n                type=str(_require(o, \"type\", f\"odometry '{oid}'\")),\n                position_m=_xy(_require(o, \"position_m\", f\"odometry '{oid}'\"),\n                               f\"odometry '{oid}'\"),\n                measure_axis_rad=(None if o.get(\"measure_axis_rad\", None) is None\n                                  else float(o[\"measure_axis_rad\"])),\n                radius_m=(None if o.get(\"radius_m\", None) is None\n                          else float(o[\"radius_m\"])),\n                encoder_cpr=(None if o.get(\"encoder_cpr\", None) is None\n                             else int(o[\"encoder_cpr\"])),\n            ))\n\n        chassis = Chassis(schema_version=int(doc[\"schema_version\"]),\n                          footprint=footprint, center_of_mass=com,\n                          drive_wheels=wheels, odometry=odo)\n        chassis.validate()\n        return chassis\n\n    def validate(self) -> None:\n        self.footprint.validate()\n        self.center_of_mass.validate()\n        if not self.drive_wheels:\n            raise SchemaError(\"chassis has no drive_wheels\")\n        ids = [w.id for w in self.drive_wheels]\n        if len(ids) != len(set(ids)):\n            raise SchemaError(\"drive_wheels have duplicate ids\")\n        for w in self.drive_wheels:\n            w.validate()\n        odo_ids = [o.id for o in self.odometry]\n        if len(odo_ids) != len(set(odo_ids)):\n            raise SchemaError(\"odometry sources have duplicate ids\")\n        for o in self.odometry:\n            o.validate()\n\n    def actuator_refs(self) -> list[str]:\n        return [w.actuator_ref for w in self.drive_wheels]\n\n\n# --------------------------------------------------------------------------- #\n# actuators.yaml\n# --------------------------------------------------------------------------- #\n@dataclass\nclass Datasheet:\n    rated_voltage_v: float\n    kv_rpm_per_v: float\n    stall_torque_nm: float\n    stall_current_a: float\n    no_load_speed_rpm: float\n    no_load_current_a: float\n    encoder_cpr: int\n    rotor_inertia_kgm2: Optional[float] = None  # None => estimated in derive.py\n\n    @staticmethod\n    def from_doc(d: Any, ctx: str) -> \"Datasheet\":\n        return Datasheet(\n            rated_voltage_v=float(_require(d, \"rated_voltage_v\", ctx)),\n            kv_rpm_per_v=float(_require(d, \"kv_rpm_per_v\", ctx)),\n            stall_torque_nm=float(_require(d, \"stall_torque_nm\", ctx)),\n            stall_current_a=float(_require(d, \"stall_current_a\", ctx)),\n            no_load_speed_rpm=float(_require(d, \"no_load_speed_rpm\", ctx)),\n            no_load_current_a=float(_require(d, \"no_load_current_a\", ctx)),\n            encoder_cpr=int(_require(d, \"encoder_cpr\", ctx)),\n            rotor_inertia_kgm2=(None if d.get(\"rotor_inertia_kgm2\", None) is None\n                                else float(d[\"rotor_inertia_kgm2\"])),\n        )\n\n\n@dataclass\nclass Physical:\n    \"\"\"Directly-measured electrical/mechanical constants (SI). Optional; when\n    present they take precedence over datasheet-derived values.\"\"\"\n    torque_constant_nm_a: Optional[float] = None   # Kt\n    back_emf_v_s: Optional[float] = None            # Ke\n    resistance_ohm: Optional[float] = None          # R\n    inductance_h: Optional[float] = None            # L\n    rotor_inertia_kgm2: Optional[float] = None      # J\n\n    @staticmethod\n    def from_doc(d: Any) -> \"Physical\":\n        if d is None:\n            return Physical()\n        g = lambda k: (None if d.get(k, None) is None else float(d[k]))\n        return Physical(\n            torque_constant_nm_a=g(\"torque_constant_nm_a\"),\n            back_emf_v_s=g(\"back_emf_v_s\"),\n            resistance_ohm=g(\"resistance_ohm\"),\n            inductance_h=g(\"inductance_h\"),\n            rotor_inertia_kgm2=g(\"rotor_inertia_kgm2\"),\n        )\n\n\n@dataclass\nclass ActuatorDef:\n    \"\"\"One actuator instance: a preset reference plus overrides, or a\n    self-contained datasheet when ``preset`` is null.\"\"\"\n    name: str\n    preset: Optional[str] = None\n    overrides: dict[str, Any] = field(default_factory=dict)\n    datasheet: Optional[Datasheet] = None\n\n    def validate(self) -> None:\n        if self.preset is None and self.datasheet is None:\n            raise SchemaError(\n                f\"actuator '{self.name}': needs either 'preset' or a \"\n                \"'datasheet' block\")\n\n\n@dataclass\nclass ActuatorSet:\n    schema_version: int\n    actuators: dict[str, ActuatorDef]\n\n    @staticmethod\n    def from_doc(doc: Any) -> \"ActuatorSet\":\n        _check_version(doc, \"actuators.yaml\")\n        raw = _require(doc, \"actuators\", \"actuators.yaml\")\n        out: dict[str, ActuatorDef] = {}\n        for name, body in raw.items():\n            body = body or {}\n            preset = body.get(\"preset\", None)\n            preset = None if preset is None else str(preset)\n            ds_raw = body.get(\"datasheet\", None)\n            out[str(name)] = ActuatorDef(\n                name=str(name),\n                preset=preset,\n                overrides=dict(body.get(\"overrides\", {}) or {}),\n                datasheet=(Datasheet.from_doc(ds_raw, f\"actuator '{name}'.datasheet\")\n                           if ds_raw is not None else None),\n            )\n        aset = ActuatorSet(schema_version=int(doc[\"schema_version\"]), actuators=out)\n        aset.validate()\n        return aset\n\n    def validate(self) -> None:\n        if not self.actuators:\n            raise SchemaError(\"actuators.yaml defines no actuators\")\n        for a in self.actuators.values():\n            a.validate()\n\n\n# --------------------------------------------------------------------------- #\n# presets/motors/*.yaml\n# --------------------------------------------------------------------------- #\n@dataclass\nclass MotorPreset:\n    name: str\n    datasheet: Datasheet\n    physical: Physical = field(default_factory=Physical)\n\n    @staticmethod\n    def from_doc(doc: Any, name: str) -> \"MotorPreset\":\n        ds = Datasheet.from_doc(_require(doc, \"datasheet\", f\"preset '{name}'\"),\n                                f\"preset '{name}'.datasheet\")\n        phys = Physical.from_doc(doc.get(\"physical\", None))\n        return MotorPreset(name=name, datasheet=ds, physical=phys)\n\n\n# --------------------------------------------------------------------------- #\n# model_error.yaml\n# --------------------------------------------------------------------------- #\n@dataclass\nclass ModelError:\n    schema_version: int\n    ratios: dict[str, float]\n    mode: str = \"ratio\"              # 'ratio' | 'manual'\n    manual_file: Optional[str] = None\n\n    @staticmethod\n    def from_doc(doc: Any) -> \"ModelError\":\n        _check_version(doc, \"model_error.yaml\")\n        mode = str(doc.get(\"mode\", \"ratio\"))\n        if mode not in (\"ratio\", \"manual\"):\n            raise SchemaError(f\"model_error.mode '{mode}' invalid \"\n                              \"(expected 'ratio' or 'manual')\")\n        me = ModelError(\n            schema_version=int(doc[\"schema_version\"]),\n            ratios={str(k): float(v) for k, v in (doc.get(\"ratios\", {}) or {}).items()},\n            mode=mode,\n            manual_file=(None if doc.get(\"manual_file\", None) is None\n                         else str(doc[\"manual_file\"])),\n        )\n        if me.mode == \"manual\" and me.manual_file is None:\n            raise SchemaError(\"model_error.mode is 'manual' but manual_file is null\")\n        return me\n\n\ndef _check_version(doc: Any, ctx: str) -> None:\n    v = _require(doc, \"schema_version\", ctx)\n    if int(v) != SCHEMA_VERSION:\n        raise SchemaError(f\"{ctx}: schema_version {v} unsupported \"\n                          f\"(this build expects {SCHEMA_VERSION})\")\n", "omni_sim_core/mechanism/derive.py": "\"\"\"Datasheet -> physical constants.\n\nInput : a motor ``Datasheet`` (+ optional measured ``Physical`` overrides) and\nthe drivetrain figures (gear ratio, wheel-side load inertia).\nOutput: a ``DerivedMotor`` holding SI constants (Kt, Ke, R, tau_stall,\nomega_noload, reflected inertia, viscous damping) and a record of *which* fields\nwere estimated rather than taken/derived from the datasheet.\n\nEstimated and measured values are never silently mixed: every estimated field is\nlisted in ``DerivedMotor.estimated`` and gets a ``# ESTIMATED`` comment when\nwritten out by ``build.py``. A rough rotor-inertia estimate also emits a warning.\n\"\"\"\nfrom __future__ import annotations\n\nimport math\nimport warnings\nfrom dataclasses import dataclass, field\nfrom typing import Optional\n\nfrom .schema import Datasheet, Physical\n\n# Rough spin-up time assumed when the rotor inertia is unknown. This is a\n# deliberately crude placeholder (a typical small BLDC free-accelerates in tens\n# of ms); it exists only so an unknown-J motor still simulates. Any value\n# derived from it is flagged ESTIMATED.\nROTOR_SPINUP_TIME_S = 0.05\n\nTWO_PI = 2.0 * math.pi\nRPM_TO_RAD_S = TWO_PI / 60.0   # [rev/min] -> [rad/s]\n\n\n@dataclass\nclass DerivedMotor:\n    torque_constant_nm_a: float          # Kt\n    back_emf_v_s: float                  # Ke  (== Kt in SI)\n    resistance_ohm: float                # R\n    inductance_h: Optional[float]        # L   (None unless measured)\n    stall_torque_nm: float               # tau_stall\n    no_load_speed_rad_s: float           # omega_noload\n    rotor_inertia_kgm2: float            # J_rotor\n    reflected_inertia_kgm2: float        # J_reflected (motor-shaft)\n    load_contribution_kgm2: float        # (J_wheel + m_share r^2) / n^2\n    damping_nms: float                   # B  (viscous, lumped)\n    estimated: set[str] = field(default_factory=set)\n\n\ndef derive_motor(datasheet: Datasheet, physical: Physical, *,\n                 gear_ratio: float,\n                 load_inertia_wheel_side_kgm2: float,\n                 spinup_time_s: float = ROTOR_SPINUP_TIME_S) -> DerivedMotor:\n    \"\"\"Derive motor-shaft physical constants.\n\n    ``load_inertia_wheel_side_kgm2`` is the wheel-side load inertia\n    (J_wheel + m_share * r_wheel^2); it is reflected to the motor shaft by 1/n^2.\n    \"\"\"\n    ds = datasheet\n    est: set[str] = set()\n\n    # Kt = 60 / (2*pi*KV)   [Nm/A], KV in rpm/V.\n    #   Derivation: Ke_SI [V*s/rad] = 1 / (KV * 2*pi/60); in SI Kt == Ke.\n    kt = 60.0 / (TWO_PI * ds.kv_rpm_per_v)\n    ke = kt                                   # SI: numerically identical\n    if physical.torque_constant_nm_a is not None:\n        kt = physical.torque_constant_nm_a\n    if physical.back_emf_v_s is not None:\n        ke = physical.back_emf_v_s\n\n    # R = V_rated / I_stall   [ohm]  (terminal resistance at stall, L*di/dt = 0)\n    r = ds.rated_voltage_v / ds.stall_current_a\n    if physical.resistance_ohm is not None:\n        r = physical.resistance_ohm\n\n    inductance = physical.inductance_h        # only if measured\n\n    # tau_stall = Kt * (I_stall - I_noload)   [Nm]\n    tau_stall = kt * (ds.stall_current_a - ds.no_load_current_a)\n\n    # omega_noload = KV * V_rated * 2*pi/60   [rad/s]\n    omega_noload = ds.kv_rpm_per_v * ds.rated_voltage_v * RPM_TO_RAD_S\n\n    # Rotor inertia: measured > datasheet > rough estimate.\n    if physical.rotor_inertia_kgm2 is not None:\n        j_rotor = physical.rotor_inertia_kgm2\n    elif ds.rotor_inertia_kgm2 is not None:\n        j_rotor = ds.rotor_inertia_kgm2\n    else:\n        # J_rotor ~ tau_stall / (omega_noload / t_acc): torque over angular\n        # acceleration needed to reach no-load speed in t_acc. Crude by design.\n        j_rotor = tau_stall / (omega_noload / spinup_time_s)\n        est.add(\"rotor_inertia_kgm2\")\n        warnings.warn(\n            f\"rotor inertia unknown; estimated J_rotor={j_rotor:.3e} kg m^2 \"\n            f\"from stall torque and a {spinup_time_s*1e3:.0f} ms spin-up \"\n            \"assumption -- provide 'rotor_inertia_kgm2' for accuracy\",\n            stacklevel=2)\n\n    # Reflected to the motor shaft: J_ref = J_rotor + load_wheel_side / n^2.\n    load_contribution = load_inertia_wheel_side_kgm2 / (gear_ratio ** 2)\n    j_reflected = j_rotor + load_contribution\n    if \"rotor_inertia_kgm2\" in est:\n        est.add(\"reflected_inertia_kgm2\")\n\n    # Viscous damping lumped from the no-load operating point: at no load the\n    # electromagnetic torque Kt*I_noload is spent on friction; attributing it\n    # all to viscous damping gives B ~ Kt*I_noload / omega_noload. This is an\n    # approximation (ignores Coulomb friction), hence flagged estimated.\n    damping = kt * ds.no_load_current_a / omega_noload\n    est.add(\"damping_nms\")\n\n    return DerivedMotor(\n        torque_constant_nm_a=kt,\n        back_emf_v_s=ke,\n        resistance_ohm=r,\n        inductance_h=inductance,\n        stall_torque_nm=tau_stall,\n        no_load_speed_rad_s=omega_noload,\n        rotor_inertia_kgm2=j_rotor,\n        reflected_inertia_kgm2=j_reflected,\n        load_contribution_kgm2=load_contribution,\n        damping_nms=damping,\n        estimated=est,\n    )\n", "omni_sim_core/mechanism/jacobian.py": "\"\"\"Drive / odometry jacobian from a wheel layout.\n\nInput : a validated ``Chassis``.\nOutput: the drive jacobian ``J`` (body twist ``[vx, vy, wz]`` -> per-wheel\nmotor-shaft angular velocity), its pseudo-inverse (odometry: wheel speeds ->\nbody twist), and the singular-configuration guard.\n\nPer-wheel (drive axis ``theta_i``, contact point ``(x_i, y_i)``, radius ``r_i``,\ngear ratio ``n_i``, motor:wheel):\n\n    omega_i = ( cos(theta_i) vx + sin(theta_i) vy\n                + (x_i sin(theta_i) - y_i cos(theta_i)) wz ) / r_i * n_i\n\nDerivation: the wheel's ground-contact point moves at\n``v + wz x r_i`` = ``[vx - wz*y_i, vy + wz*x_i]``; its roll speed is the\nprojection onto the drive axis, divided by ``r_i`` (wheel rad/s) and multiplied\nby ``n_i`` (motor shaft rad/s, which is what the encoder sees). ``reverse``\nflips the row sign.\n\nCoordinates are the *geometric centre* (base_link). A centre-of-mass offset is\nNOT folded into the kinematics here -- it belongs in the mass matrix as the\ntranslation/rotation coupling terms (see ``build_mass_matrix``).\n\"\"\"\nfrom __future__ import annotations\n\nimport logging\n\nimport numpy as np\n\nfrom .schema import Chassis\n\nlogger = logging.getLogger(__name__)\n\n# Above this 2-norm condition number the wheel set cannot robustly span the\n# 3-DOF body twist (e.g. two wheels, or all drive axes parallel).\nCONDITION_NUMBER_LIMIT = 1.0e6\n\n\nclass SingularConfigError(ValueError):\n    \"\"\"Raised when the drive jacobian is too ill-conditioned to invert.\"\"\"\n\n\ndef build_drive_jacobian(chassis: Chassis) -> np.ndarray:\n    \"\"\"Return the ``(n_wheels, 3)`` drive jacobian for a chassis.\"\"\"\n    rows = []\n    for w in chassis.drive_wheels:\n        th = w.drive_axis_rad\n        x, y = w.position_m\n        c, s = np.cos(th), np.sin(th)\n        gain = (w.gear_ratio / w.radius_m) * (-1.0 if w.reverse else 1.0)\n        rows.append(gain * np.array([c, s, x * s - y * c]))\n    return np.asarray(rows, dtype=float)\n\n\nclass DriveJacobian:\n    \"\"\"Drive jacobian with its inverse and a condition-number guard.\"\"\"\n\n    def __init__(self, chassis: Chassis) -> None:\n        self.chassis = chassis\n        self.J = build_drive_jacobian(chassis)\n        self.condition_number = float(np.linalg.cond(self.J))\n        logger.info(\"drive jacobian: %d wheels, condition number %.3g\",\n                    self.J.shape[0], self.condition_number)\n        if not np.isfinite(self.condition_number) or \\\n                self.condition_number > CONDITION_NUMBER_LIMIT:\n            raise SingularConfigError(\n                f\"drive jacobian condition number {self.condition_number:.3g} \"\n                f\"exceeds {CONDITION_NUMBER_LIMIT:.0e}: the wheels do not span \"\n                \"all 3 DOF (too few wheels, or parallel drive axes)\")\n        self.J_pinv = np.linalg.pinv(self.J)\n\n    @property\n    def n_wheels(self) -> int:\n        return self.J.shape[0]\n\n    def wheel_speeds_from_body(self, body_twist: np.ndarray) -> np.ndarray:\n        \"\"\"Body twist [vx, vy, wz] -> motor-shaft angular velocities [rad/s].\"\"\"\n        return self.J @ np.asarray(body_twist, dtype=float)\n\n    def body_from_wheel_speeds(self, wheel_omega: np.ndarray) -> np.ndarray:\n        \"\"\"Odometry: motor-shaft angular velocities -> body twist (min-norm).\"\"\"\n        return self.J_pinv @ np.asarray(wheel_omega, dtype=float)\n\n\ndef build_mass_matrix(chassis: Chassis) -> np.ndarray:\n    \"\"\"3x3 body-frame mass matrix about the geometric centre.\n\n    With the centre of mass at ``(cx, cy)`` relative to base_link, mass ``m`` and\n    inertia about the CoM ``Izz``, the mass matrix picks up off-diagonal\n    translation/rotation coupling::\n\n        M = [[ m,      0,     -m*cy          ],\n             [ 0,      m,      m*cx          ],\n             [-m*cy,   m*cx,   Izz + m*(cx^2+cy^2) ]]\n\n    The off-diagonal terms vanish only when the CoM sits on the geometric centre.\n    \"\"\"\n    com = chassis.center_of_mass\n    m = com.mass_kg\n    cx, cy = com.position_m\n    izz_center = com.inertia_zz_kgm2 + m * (cx * cx + cy * cy)  # parallel axis\n    return np.array([\n        [m,        0.0,      -m * cy],\n        [0.0,      m,         m * cx],\n        [-m * cy,  m * cx,    izz_center],\n    ])\n\n\ndef build_odometry_jacobian(chassis: Chassis, *, with_gyro: bool = False\n                            ) -> tuple[np.ndarray, list[str]]:\n    \"\"\"Measurement matrix for the *standalone* odometry units, plus their ids.\n\n    Rows map a body twist ``[vx, vy, wz]`` to what each unit measures:\n\n    ``dead_wheel``  its own angular velocity [rad/s]. Same projection as a\n                    drive wheel -- contact point velocity onto the measure\n                    axis, divided by the radius -- but with **no gear ratio**:\n                    a dead wheel's encoder is on the wheel itself.\n    ``optical``     two rows, the planar velocity at its mounting point\n                    resolved in the body frame [m/s].\n\n    ``with_gyro`` appends a ``[0, 0, 1]`` row for a yaw-rate measurement. This\n    is usually not optional in practice: two dead wheels give two equations for\n    three unknowns, so the twist is *not observable* from them alone. The\n    caller is expected to check (see ``odometry_observability``) rather than\n    discover it as a silently wrong estimate.\n\n    Coordinates are the geometric centre (base_link), matching\n    ``build_drive_jacobian``.\n    \"\"\"\n    rows: list[np.ndarray] = []\n    ids: list[str] = []\n    for o in chassis.odometry:\n        x, y = o.position_m\n        if o.type == \"dead_wheel\":\n            th = float(o.measure_axis_rad)\n            c, s = np.cos(th), np.sin(th)\n            rows.append(np.array([c, s, x * s - y * c]) / float(o.radius_m))\n            ids.append(o.id)\n        elif o.type == \"optical\":\n            rows.append(np.array([1.0, 0.0, -y]))\n            rows.append(np.array([0.0, 1.0, x]))\n            ids.extend([f\"{o.id}.vx\", f\"{o.id}.vy\"])\n        else:                                   # schema validates, belt and braces\n            raise ValueError(f\"odometry '{o.id}': unsupported type {o.type!r}\")\n    if with_gyro:\n        rows.append(np.array([0.0, 0.0, 1.0]))\n        ids.append(\"gyro.wz\")\n    if not rows:\n        return np.zeros((0, 3)), []\n    return np.asarray(rows, dtype=float), ids\n\n\ndef odometry_observability(matrix: np.ndarray) -> tuple[bool, float]:\n    \"\"\"``(is_observable, condition_number)`` for an odometry measurement set.\n\n    A rank-deficient set cannot recover the twist at all; an ill-conditioned\n    one recovers it while amplifying noise. Both are worth refusing loudly:\n    the failure mode of using them anyway is a pose estimate that looks\n    plausible and is wrong in a direction nobody chose.\n    \"\"\"\n    if matrix.shape[0] < 3:\n        return False, float(\"inf\")\n    cond = float(np.linalg.cond(matrix))\n    ok = np.linalg.matrix_rank(matrix) == 3 and cond < CONDITION_NUMBER_LIMIT\n    return ok, cond\n"}, "hashes": {"omni_sim_core/__init__.py": "fdd378bc7047b327", "omni_sim_core/mechanism/__init__.py": "d51ba8fb7dda5126", "omni_sim_core/mechanism/schema.py": "c31f3d87016c138d", "omni_sim_core/mechanism/derive.py": "28b84fb243665ad8", "omni_sim_core/mechanism/jacobian.py": "0cc2cb0fe8f8aeab"}, "presets": {"ak40_10_v3": {"datasheet": {"rated_voltage_v": 24.0, "kv_rpm_per_v": 100.0, "stall_torque_nm": 24.5, "stall_current_a": 60.0, "no_load_speed_rpm": 2400.0, "no_load_current_a": 1.2, "rotor_inertia_kgm2": null, "encoder_cpr": 16384}, "physical": {"resistance_ohm": 0.1}}, "generic_dc": {"datasheet": {"rated_voltage_v": 12.0, "kv_rpm_per_v": 300.0, "stall_torque_nm": 0.5, "stall_current_a": 8.0, "no_load_speed_rpm": 3600.0, "no_load_current_a": 0.4, "rotor_inertia_kgm2": 2e-06, "encoder_cpr": 2048}}, "m2006_c610": {"datasheet": {"rated_voltage_v": 24.0, "kv_rpm_per_v": 17.3, "stall_torque_nm": 1.0, "stall_current_a": 3.0, "no_load_speed_rpm": 415.0, "no_load_current_a": 0.3, "rotor_inertia_kgm2": 1.5e-05, "encoder_cpr": 8192}}, "m3508_c620": {"datasheet": {"rated_voltage_v": 24.0, "kv_rpm_per_v": 20.0, "stall_torque_nm": 4.77, "stall_current_a": 10.5, "no_load_speed_rpm": 480.0, "no_load_current_a": 0.5, "rotor_inertia_kgm2": 0.0001, "encoder_cpr": 8192}}}, "chassis": {"schema_version": 1, "footprint": {"shape": "square", "size_m": 0.7}, "center_of_mass": {"position_m": [0.0, 0.0], "mass_kg": 15.0, "inertia_zz_kgm2": 0.35}, "drive_wheels": [{"id": "fl", "position_m": [0.34, -0.34], "drive_axis_rad": 2.356, "radius_m": 0.0508, "gear_ratio": 6.0, "actuator_ref": "m3508_fl", "reverse": false}, {"id": "fr", "position_m": [-0.34, -0.34], "drive_axis_rad": 0.785, "radius_m": 0.0508, "gear_ratio": 6.0, "actuator_ref": "m3508_fr", "reverse": false}, {"id": "rl", "position_m": [-0.34, 0.34], "drive_axis_rad": 3.927, "radius_m": 0.0508, "gear_ratio": 6.0, "actuator_ref": "m3508_rl", "reverse": false}, {"id": "rr", "position_m": [0.34, 0.34], "drive_axis_rad": 5.498, "radius_m": 0.0508, "gear_ratio": 6.0, "actuator_ref": "m3508_rr", "reverse": false}], "odometry": [{"id": "dw_x", "type": "dead_wheel", "position_m": [0.0, 0.15], "measure_axis_rad": 0.0, "radius_m": 0.024, "encoder_cpr": 4096}, {"id": "dw_y", "type": "dead_wheel", "position_m": [0.15, 0.0], "measure_axis_rad": 1.5708, "radius_m": 0.024, "encoder_cpr": 4096}]}};
